from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT = Path("BizPilot_Submission")
OUT.mkdir(exist_ok=True)
GREEN = colors.HexColor("#145A42")
GOLD = colors.HexColor("#C58A24")
INK = colors.HexColor("#1F2937")
MUTED = colors.HexColor("#667085")
PALE = colors.HexColor("#EEF7F2")

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="CoverTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=30, leading=35, textColor=GREEN, spaceAfter=12))
styles.add(ParagraphStyle(name="CoverSub", parent=styles["Normal"], fontSize=14, leading=20, textColor=MUTED, alignment=TA_CENTER))
styles.add(ParagraphStyle(name="H1x", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=19, leading=24, textColor=GREEN, spaceBefore=8, spaceAfter=10))
styles.add(ParagraphStyle(name="H2x", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=13, leading=17, textColor=INK, spaceBefore=8, spaceAfter=5))
styles.add(ParagraphStyle(name="Bodyx", parent=styles["BodyText"], fontName="Helvetica", fontSize=10.2, leading=15, textColor=INK, spaceAfter=7))
styles.add(ParagraphStyle(name="Smallx", parent=styles["BodyText"], fontSize=8.5, leading=12, textColor=MUTED))
styles.add(ParagraphStyle(name="Shot", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=11, leading=15, textColor=GREEN, alignment=TA_CENTER, borderColor=GREEN, borderWidth=1, borderPadding=20, spaceBefore=8, spaceAfter=12))

def header_footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(colors.HexColor("#D9E5DF")); canvas.line(18*mm, 15*mm, 192*mm, 15*mm)
    canvas.setFont("Helvetica", 8); canvas.setFillColor(MUTED); canvas.drawString(18*mm, 10*mm, "BizPilot | Bengal Boots | Topic E: SME Finance Copilot")
    canvas.drawRightString(192*mm, 10*mm, str(doc.page)); canvas.restoreState()

def cover(title, subtitle):
    return [Spacer(1, 55*mm), Paragraph("BIZPILOT", styles["CoverTitle"]), Paragraph(title, styles["CoverTitle"]), Spacer(1, 6*mm), Paragraph(subtitle, styles["CoverSub"]), Spacer(1, 10*mm), Paragraph("Bengal Boots · Competition Submission · 20 October 2026", styles["CoverSub"]), PageBreak()]

def p(text): return Paragraph(text, styles["Bodyx"])
def h1(text): return Paragraph(text, styles["H1x"])
def h2(text): return Paragraph(text, styles["H2x"])
def bullets(items): return [Paragraph("• " + x, styles["Bodyx"]) for x in items]
def table(rows, widths=None):
    t=Table([[Paragraph(str(c), styles["Smallx"]) for c in row] for row in rows], colWidths=widths, repeatRows=1, hAlign="LEFT")
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),GREEN),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("GRID",(0,0),(-1,-1),.5,colors.HexColor("#D8E0DC")),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,PALE]),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),7),("RIGHTPADDING",(0,0),(-1,-1),7),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)])); return t

def build(name, title, subtitle, story):
    doc=SimpleDocTemplate(str(OUT/name),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=18*mm,bottomMargin=20*mm,title=title,author="Bengal Boots")
    doc.build(cover(title,subtitle)+story,onFirstPage=header_footer,onLaterPages=header_footer)

technical=[]
technical += [h1("1. Business problem"),p("Bengal Boots is a real small online footwear business that sources footwear from vendors and sells mainly through Facebook. The owner must balance sales volume with profit per delivered order while managing courier outcomes, advertising, influencer spending, discounts, free delivery and restocking decisions."),p("Courier reports show collections and delivery outcomes but do not contain all business costs. BizPilot combines anonymized courier aggregates with owner-entered assumptions, then makes each calculation traceable.")]
technical += [h1("2. Topic E alignment"),table([["Topic E requirement","BizPilot implementation"],["Business financial analysis","Revenue, direct cost, profit, margin, order outcomes and trends"],["Cash-flow management","Three to twelve-month forecast with shortage and low-buffer alerts"],["Financing matching","Educational comparison of loan, supplier credit, revenue-based finance and no financing"],["AI tools and explanations","Responses API chooses deterministic Python tools and reports the tool used"]],[55*mm,115*mm])]
technical += [h1("3. Architecture"),p("The application uses Streamlit for the interface, pandas for validated local data processing, deterministic Python functions for finance logic, and the official OpenAI Python SDK for the Responses API."),table([["Layer","Responsibility"],["app.py","Seven application sections, date range, forms and visualizations"],["data_loader.py / privacy.py","Workbook parsing, schema checks, PII removal and redaction"],["finance.py","Courier KPIs, profit, pricing, cash flow and financing math"],["tools.py","Six tool schemas and local dispatch"],["agent.py","Responses API loop, sanitized history and activity evidence"]],[48*mm,122*mm])]
technical += [h1("4. AI tool-calling workflow"),p("The user asks a question. The Responses API selects a declared function. BizPilot runs that function locally against the selected date range. The app returns only aggregated tool output to the model. The model explains known facts, owner assumptions and calculated estimates. The activity log records the selected tool, sanitized inputs, summary and confirmation requirement."),p("The model never calculates financial figures independently. Missing essential inputs trigger a follow-up question. No tool can make a payment, borrow money or place an order.")]
technical += [h1("5. Deterministic calculations and data flow"),p("The bundled Orders worksheet contains 65 anonymized rows visible in source screenshots. It is partial evidence, not the full Steadfast history. Unknown product values remain missing. A zero COD value remains present with a review flag."),table([["Metric","Verified extract result"],["Delivered COD","BDT 115,202"],["Product cost","52 delivered orders x BDT 1,100 = BDT 57,200"],["Courier charges","BDT 7,685 across all visible rows"],["Estimated profit","BDT 51,016 before owner-entered unknown expenses"],["Delivery success","52 / 65 = 80.0%"]],[65*mm,105*mm]),p("Returned or cancelled footwear remains saleable, so BizPilot does not recognize its purchase cost again. Partial-delivery COD is collected revenue, while unknown partial product quantity remains excluded and disclosed.")]
technical += [h1("6. Pricing and marketing analysis"),p("The pricing simulator replaces constant-volume assumptions with owner-entered demand or a transparent price-sensitivity curve. It includes unit cost, packaging, courier cost, advertising allocation, discounts, cancellation risk and competitor price. Each scenario reports expected orders, successful deliveries, revenue, costs, profit, margin, contribution and break-even orders."),p("Campaign analysis calculates customer acquisition cost, return on advertising spend, campaign contribution and break-even orders. Missing spend, attributed orders, revenue or contribution produces a request for information instead of an invented result.")]
technical += [h1("7. Cash-flow alerts and financing comparison"),p("The cash forecast rolls opening cash forward for at least three months using expected inflows and owner-entered costs. Negative balances produce shortage alerts; small buffers produce low-cash warnings. Suggested actions remain educational."),p("Financing options use fictional rates to compare approximate total repayment and monthly burden. The no-financing option remains visible. Every result states that it is a simulated educational example and requires owner confirmation.")]
technical += [h1("8. Privacy and security"),*bullets(["Names, phone numbers, addresses, emails and related customer fields are removed locally.","Raw courier rows do not enter AI requests. Tools return aggregates only.","The API key lives in .env, which Git and the source ZIP exclude.","The activity log excludes keys and customer PII.","The app remains useful in dashboard-only mode when AI credentials or billing are unavailable."])]
technical += [h1("9. Limitations"),p("The screenshot extract is incomplete and cannot establish complete historical performance. Product information is missing. Partial-delivery product quantity is unknown. Owner-entered expenses may be incomplete. Demand curves, campaign attribution, cash forecasts and financing rates are simulations. BizPilot provides educational decision support rather than accounting, lending, investment, legal or tax advice.")]
build("01_BizPilot_Technical_Documentation.pdf","Technical Documentation","Topic E: SME Finance Copilot",technical)

demo=[h1("Demo goal and timing"),table([["Segment","Time"],["Opening and data scope","0:00-0:25"],["AI Finance Copilot","0:25-1:20"],["Dashboard and pricing","1:20-2:35"],["Cash flow and financing","2:35-3:40"],["Privacy and activity log","3:40-4:35"],["Close","4:35-4:50"]],[90*mm,70*mm]),h1("Presenter script"),h2("0:00-0:25 | Opening"),p("BizPilot is an SME Finance Copilot built for Bengal Boots, a real online footwear business. The default data is a partial anonymized extract transcribed from rows visible in Steadfast screenshots, so I will not present it as the complete business history."),h2("0:25-1:20 | AI Finance Copilot"),p("Open AI Finance Copilot. Ask: How is my business performing? Explain that the model selects a finance tool, Python calculates the numbers, and the model explains the result. If live API billing is unavailable, state that the same tool flow is covered by mocked tests and demonstrate the local dashboard instead."),h2("1:20-2:35 | Performance and pricing"),p("Open Business Dashboard. Point to 65 visible orders, 52 deliveries, 80.0% delivery success and the preserved zero-COD anomaly. Expand the cost calculation. Show that returned footwear is resaleable, so cancelled orders do not consume the BDT 1,100 purchase cost. Open Pricing and Marketing Simulator. Compare BDT 1,800, BDT 2,000 and BDT 2,500. Change price sensitivity to show that volume changes with price."),h2("2:35-3:40 | Cash flow and financing"),p("Open Cash-Flow Forecast. Change current cash or planned inventory until an alert appears. Explain the rolling balance and suggested actions. Open Financing Options. Compare total cost and monthly burden, and point out the no-financing choice and educational disclaimer."),h2("3:40-4:35 | Privacy and evidence"),p("Open Data Upload. Show the seven required columns and the privacy warning. Explain that personal columns are removed locally. Open Agent Activity Log. Show tool name, sanitized inputs, result summary, confirmation flag and the downloadable evidence CSV."),h2("4:35-4:50 | Close"),p("BizPilot turns courier records and owner assumptions into explainable decisions while keeping calculations deterministic, customer data local and every financial action under owner control."),PageBreak(),h1("Recording checklist"),*bullets(["Use a clean browser window at 100% zoom.","Do not show .env, API keys, raw screenshots or customer data.","Keep the partial-data warning visible when discussing metrics.","State that pricing, forecasts and financing are simulations.","Pause after each page change so judges can read the result."])]
build("03_BizPilot_Demo_Video_Script.pdf","Demo Video Script","Under five minutes · Competition recording guide",demo)

security=[h1("Assessment scope"),p("This self-assessment covers BizPilot's local Streamlit application, the anonymized Steadfast extract, the OpenAI Responses API integration and exported execution evidence."),h1("Security controls"),table([["Area","Control","Status"],["API key","Environment-only .env storage; excluded from Git and ZIP","Implemented"],["PII removal","Local column detection for name, phone, address, email and related fields","Implemented"],["AI payload","Aggregated tool results and redacted chat text only","Implemented"],["Permission tiers","Read-only analysis by default; simulated recommendations; no transaction capability","Implemented"],["Owner confirmation","Required before any simulated financing or operational action","Implemented"],["Logging","Sanitized inputs and summaries; no key or raw customer records","Implemented"]],[35*mm,100*mm,35*mm]),h1("Permission tiers"),*bullets(["Tier 1 - Local read and analysis: courier parsing, metrics and simulations.","Tier 2 - AI explanation: aggregated totals sent through declared tools when configured.","Tier 3 - Simulated action preparation: requires explicit owner confirmation.","Prohibited: payments, loan applications, banking access, inventory purchasing and customer outreach."]),h1("Known risks and mitigations"),table([["Risk","Mitigation"],["A key is exposed or committed","Rotate immediately; .env ignored; secret scan before packaging"],["PII appears in an upload","Drop matching columns locally and show a warning"],["PII appears in chat","Redact common emails and Bangladesh phone numbers before API calls"],["Incomplete screenshot history biases results","Persistent partial-data warning and date range disclosure"],["Model invents a number","Require tool use; deterministic Python owns calculations"],["Bad assumptions create bad forecasts","Display assumptions, confidence and editable inputs"],["Unauthorized real-world action","No transactional integrations; owner confirmation safeguard"]],[55*mm,115*mm]),h1("Residual risk"),p("Free-text redaction cannot guarantee detection of every identifier. Users must avoid entering personal data. The partial dataset cannot support complete historical conclusions. API availability, billing and model access remain external dependencies. The owner must verify decisions and maintain secure endpoint and file access."),h1("Conclusion"),p("BizPilot applies data minimization, deterministic computation and human confirmation appropriately for a competition prototype. Production deployment would require stronger authentication, access control, encrypted storage, audit retention policy and formal privacy review.")]
build("05_BizPilot_Security_Self_Assessment.pdf","Security Self-Assessment","Privacy, permissions and safeguards",security)

evidence=[h1("Verification summary"),table([["Check","Result"],["Automated tests","26 passed in 0.69 seconds"],["Default dataset","65 anonymized screenshot-derived rows"],["Order outcomes","52 delivered, 7 cancelled, 6 partial deliveries"],["Delivery success","80.0%"],["Preserved anomaly","1 zero-COD row flagged for review"],["Application health","Streamlit health endpoint returned ok"]],[70*mm,100*mm]),Paragraph("ADD SCREENSHOT 1 HERE: AI Finance Copilot question and answer",styles["Shot"]),Paragraph("ADD SCREENSHOT 2 HERE: Business Dashboard with data-source warning",styles["Shot"]),h1("Application features"),*bullets(["AI chat with Responses API function calling and conversation history.","Date-filtered dashboard with courier, revenue, cost and profit metrics.","Demand-sensitive pricing and campaign analysis.","Three to twelve-month cash forecast with alerts.","Educational financing comparison including no financing.","Validated uploads and downloadable template.","Downloadable anonymized Agent Activity Log."]),Paragraph("ADD SCREENSHOT 3 HERE: Pricing scenarios and assumptions",styles["Shot"]),Paragraph("ADD SCREENSHOT 4 HERE: Cash-flow alert",styles["Shot"]),PageBreak(),h1("Example tool executions"),table([["Tool","Example output"],["analyze_business_finances","BDT 115,901 recognized revenue; BDT 51,016 estimated profit before unknown expenses"],["analyze_courier_performance","52 delivered; 7 cancelled; 6 partial; 80.0% success"],["compare_pricing_scenarios","BDT 1,800 / 2,000 / 2,500 with demand sensitivity and cancellation risk"],["forecast_cash_flow","Monthly opening, inflow, outflow, closing balance and shortage flag"],["compare_financing_options","Loan, supplier credit, revenue-based finance and no financing"]],[58*mm,112*mm]),h1("Activity logging and safeguards"),p("Each analytical response records UTC date and time, the user question, selected tool, sanitized inputs, a compact result summary, whether confirmation was required and final status. The downloadable CSV provides competition execution evidence without API keys or customer PII."),p("The application cannot perform a payment, loan, bank operation, campaign purchase or inventory order. Financing outputs set confirmation_required to true. The system prompt requires owner confirmation before preparing any simulated action."),Paragraph("ADD SCREENSHOT 5 HERE: Financing comparison and disclaimer",styles["Shot"]),Paragraph("ADD SCREENSHOT 6 HERE: Expanded Agent Activity Log",styles["Shot"]),h1("Data provenance and limitations"),p("The default workbook contains only anonymized rows transcribed from visible Steadfast screenshots. It is not the full business history. Product values are unknown and remain missing. One zero COD value remains included and flagged. Forecasts, demand scenarios and financing options are simulations."),h1("Submission checks"),*bullets(["No .env or API key included.","No passport or identity documents included.","No customer names, phone numbers, addresses or raw screenshots included.","Source ZIP excludes virtual environments, caches, Git metadata and private files."])]
build("06_BizPilot_Execution_Evidence.pdf","Execution Evidence","Tests, tool runs and screenshot placement guide",evidence)
